using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;public class PuzzleProximityVignette : MonoBehaviour{    [SerializeField] public Transform playerTransform;    [SerializeField] public Camera playerCamera;    [SerializeField] public int playerIndex = 0;    [SerializeField] public Volume playerVolume;    [SerializeField] public float nearDistance = 3f;    [SerializeField] public float farDistance = 12f;    [Range(0f, 1f)] [SerializeField] public float maxVignetteIntensity = 0.35f;    [SerializeField] public float easeTime = 0.15f;    [SerializeField] public List<PuzzleBase> explicitPuzzleTargets = new List<PuzzleBase>();    [SerializeField] public float autoRefreshSeconds = 0f;    [SerializeField] public bool onlyUnsolved = true;    [SerializeField] public bool preferMatchSideTargets = true;    [SerializeField] public bool onlyVignetteOnCorrectSide = true;    [Range(0f, 180f)] [SerializeField] public float correctSideAngleThreshold = 90f;    private Vignette _vignette;    private float _targetIntensity;    private float _currentVelocity;    private float _timeSinceRefresh;    private PuzzleBase[] _cachedPuzzles;    private Camera ResolvePlayerCamera()    {        if (playerCamera != null) return playerCamera;        var brains = Object.FindObjectsOfType<Cinemachine.CinemachineBrain>(true);        Camera best = null;        for (int i = 0; i < brains.Length; i++)        {            var cam = brains[i] != null ? brains[i].GetComponent<Camera>() : null;            if (cam == null) continue;            var r = cam.rect;            bool isLeft = (r.xMax <= 0.51f) || (r.x <= 0.01f && r.width <= 0.51f);            bool isRight = (r.xMin >= 0.49f) || (r.x >= 0.49f);            if ((playerIndex == 0 && isLeft) || (playerIndex == 1 && isRight))            {                best = cam;                break;            }        }        if (best != null) return best;        if (Camera.main != null) return Camera.main;        return GetComponent<Camera>();    }    private void Awake()    {        if (playerTransform == null)        {            if (playerCamera == null) playerCamera = GetComponent<Camera>();            playerTransform = (playerCamera != null) ? playerCamera.transform : transform;        }    }    private void Start()    {        //EnsureVignette();        CachePuzzles(true);           }    private void Update()    {        if (playerTransform == null) return;        if (autoRefreshSeconds > 0f)        {            _timeSinceRefresh += Time.unscaledDeltaTime;            if (_timeSinceRefresh >= autoRefreshSeconds)            {                CachePuzzles(false);                _timeSinceRefresh = 0f;            }        }        GetNearestPuzzle(playerTransform.position, out float nearest, out Transform sideTarget);        float t = 0f;        if (float.IsFinite(nearest))        {            t = Mathf.InverseLerp(farDistance, nearDistance, nearest);            t = t * t * (3f - 2f * t);            if (onlyVignetteOnCorrectSide && sideTarget != null && !IsPlayerOnCorrectSideOf(sideTarget))                t = 0f;        }        _targetIntensity = t * maxVignetteIntensity;        if (_vignette != null)        {            float current = _vignette.intensity.value;            float delta = Time.unscaledDeltaTime / Mathf.Max(0.0001f, easeTime);            float next = Mathf.MoveTowards(current, _targetIntensity, delta);            _vignette.intensity.value = next;        }    }    private void EnsureVignette()    {        playerVolume.isGlobal = true;        if (playerVolume.profile == null)        {            playerVolume.profile = ScriptableObject.CreateInstance<VolumeProfile>();        }        var cam = ResolvePlayerCamera();        playerCamera = cam;        if (cam == null)        {                   }        else        {            var data = cam.GetComponent<UniversalAdditionalCameraData>();            if (data != null)            {                data.renderPostProcessing = true;                int volLayer = playerVolume.gameObject.layer;                if (volLayer >= 0 && volLayer < 32)                {                    data.volumeLayerMask |= (1 << volLayer);                }                           }        }        if (!playerVolume.profile.TryGet(out _vignette))        {            _vignette = playerVolume.profile.Add<Vignette>(true);        }        if (_vignette != null)        {            playerVolume.priority = Mathf.Max(playerVolume.priority, 100f);            playerVolume.weight = 1f;            _vignette.intensity.overrideState = true;            _vignette.intensity.value = 0f;            _vignette.smoothness.overrideState = true;            _vignette.smoothness.value = 0.9f;            _vignette.color.overrideState = true;            _vignette.color.value = Color.black;        }    }    private void CachePuzzles(bool initial)    {        if (explicitPuzzleTargets != null && explicitPuzzleTargets.Count > 0)        {            _cachedPuzzles = explicitPuzzleTargets.ToArray();            return;        }        _cachedPuzzles = Object.FindObjectsOfType<PuzzleBase>(true);           }    private void GetNearestPuzzle(Vector3 from, out float distance, out Transform sideTarget)    {        distance = float.PositiveInfinity;        sideTarget = null;        var puzzles = _cachedPuzzles;        if (puzzles == null || puzzles.Length == 0) return;        for (int i = 0; i < puzzles.Length; i++)        {            var p = puzzles[i];            if (p == null || !p.gameObject.activeInHierarchy) continue;            if (onlyUnsolved && p.isSolved) continue;            Transform target = null;            if (preferMatchSideTargets && p is MatchBase m)            {                if (playerIndex == 0)                    target = m.leftQuad != null ? m.leftQuad.transform : null;                else                    target = m.rightQuad != null ? m.rightQuad.transform : null;            }            if (target == null) target = p.transform;            float d = Vector3.Distance(from, target.position);            if (d < distance)            {                distance = d;                sideTarget = target;            }        }    }    private bool IsPlayerOnCorrectSideOf(Transform quadTransform)    {        if (quadTransform == null || playerTransform == null) return true;        Vector3 toPlayer = (playerTransform.position - quadTransform.position).normalized;        float dot = Vector3.Dot(quadTransform.forward, toPlayer);        float cosThreshold = Mathf.Cos(correctSideAngleThreshold * Mathf.Deg2Rad);        return dot >= cosThreshold;    }}